      "raw_content": "카페홈\n좌담회/설문/주부알바\n가입\n검색\n메뉴\n▶설문 신청(당일 현금)~아시분과 신청가능\n앱 열기\n▶8/10~15 ]음식물 처리기 관련 조사 /만 나이 65세 이하 남녀\n본문 기타 기능\n하늘\n카페매니저\n채팅\n작성일\n2026.08.05. 10:13\n조회 93\n▶8/10~15 ]음식물 처리기 관련 조사 /만 나이 65세 이하 남녀\n=============================\n-만 나이 65세 이하 남녀로 독립 1인 가구, 신혼(2인 가구)/영유아 자녀 있는 가구, 중고등 학생 자녀 2인 이상과 함께 사는 가구, 부모와 함께 사는 성인(본인)\n* 현재 가정에서 음식물 처리기를 사용자나 향후 6개월 이내에 음식물 처리기 구매/렌탈 의향자\n-일정: 8월 10일~8월15일 중 통화후 결정\n-진행 방법 : 설문조사 1시간30분~2시간 사이 진행 후 몇명을 선정하여 좌담회 1시간 30분 진행합니다.\n(*설문 조사와 좌담회 모두 가능하신 분만 신청 바랍니다.)\n-------------------------------------------------------------------\n* 소요 시간: 설문조사 1시간 30분~2시간 사이 + 좌담회 1시간 30분 소요\n* 진행 장소: 방배동\n* 참석비: 설문조사 4만원+ 좌담회 4만원\n-------------------------------------------------------------------\n▶기재 사항\n1. 이름/성별\n2. 만 나이 (주민번호 앞자리 여섯자리 모두 기재)\n3. 전화번호 (집/휴대번호)\n4. 거주지 (구/동) / 서울 및 수도권 해당\n5. 현재 함께 사는 가족 인원수/ 자녀 있는 분은 자녀 나이 기록\n6. 하시는 일\n7. 주거 형태\n8. (1)현재 음식물처리기 사용자는 브랜드와 모델명(제품명)/ 구매or 렌탈 여부/ 사용 기간 /사용 빈도\n(2) 향후 음식물처리기 의향자는 구매or 렌탈 여부/ 예상 구입 시기\n9. 현재 가정내 수전(물) 연결하여 사용중인 가전 제품 기록\n10. 현재 스마트폰 가전앱 사용 여부\n-\n[아래 URL에 (클릭!!)하여 신청해 주세요].(스마트폰도 가능!!)]\nhttps://forms.gle/QgYAqWEDLmavyezF7\n좋아요\n0\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n지금 가입하고 댓글에 참여해보세요!\n전체글\n▶2026년 유튜브/인스타/틱톡 활동하는분 패널 / 만 16 - 44세 남녀(고등학생포함)~~100명\n하늘\n26.08.05.\n댓글\n0\n▶8/10~15 ]음식물 처리기 관련 조사 /만 나이 65세 이하 남녀\n하늘\n26.08.05.\n댓글\n0\n▶8/13 ]더마화장품 관련 좌담회 / 만 25~49세 여성\n하늘\n26.08.05.\n댓글\n0\n▶8/18~20 ]우유 관련 좌담회 /만15~64세 남녀\n하늘\n26.08.05.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n좌담회/설문/주부알바\n 카페에 가입해 보세요!\n가입하면 1만개의 글을 볼 수 있어요\n10초 만에 가입하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
