      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n8월~총직원수 10명이상 마케팅 대행사 다니시는분 온라인 인터뷰\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.08.05. 19:54\n조회 19\n구독\n8월~총직원수 10명이상 마케팅 대행사 다니시는분 온라인 인터뷰\n마케팅 에이전시 다시는분 온라인 인터뷰\n신청하신분은 재신청 안하셔도 됩니다\n<조사대상>\n-아래 업무를 하나라도 하고계시는 마케팅 대행사 근무자 (명함 증빙 필요) (명함 증빙 필요)(총직원수 10명이상)\n-유튜브, 인스타그램 등의 플랫폼을 사용한 업무 필수\n• 인플루언서 마케팅 에이전시 - 브랜드의 인플루언서 캠페인 기획 및 운영\n• 크리에이터/탤런트 에이전시 - 크리에이터 관리 및 비즈니스 기회 발굴\n• 소셜 미디어 에이전시 - 브랜드의 소셜 미디어 콘텐츠, 채널, 캠페인 관리\n• 제휴/성과 중심 에이전시 - 클릭, 전환, 매출, ROI 등 측정 가능한 성과 중심\n• 커머스/라이브스트림 에이전시 - 소셜 쇼핑, 라이브 스트림 판매, 크리에이터 주도형 커머스 전문 에이전시\n<조사방법>\n- 온라인 줌 화상 1:1 인터뷰로 진행\n- 조사시간 90분내\n<조사 진행 일정>\n8월 중/ 참여 날짜 및 시간은 조율\n<사례비>\n80,000원\n<신청링크>\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\nhttps://survey-insight.com/?ACCESS_KEY=a18cf48e-5a0c-4b17-87e5-bc209b535c68&UID=\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\n* 신청자가 많아 마감된 대상 조건/그룹이거나 조건에 맞지 않는 부분이 있으면\n연락이 가지 않을 수도 있으니 양해바랍니다.\n좋아요\n0\n송파구의 더 많은 인기글 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n8월~9월초) 수도권 거주 20~50대 남/여) 통신사 이용고객 관련 다이어리 + 홈비짓\n좌담회알바좌담회카페\n26.08.05.\n댓글\n0\n8월~총직원수 10명이상 마케팅 대행사 다니시는분 온라인 인터뷰\n좌담회알바좌담회카페\n26.08.05.\n댓글\n0\n8/19~21) 만 18~39세 성인 남녀: 리그오브레전드 플레이어 관련 좌담회\n좌담회알바좌담회카페\n26.08.05.\n댓글\n0\n모바일패널 모집 안내\n좌담회알바좌담회카페\n26.08.05.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
