      "raw_content": "미용·에스테틱 좌담회-만20~60세 남녀 9/2[사례비 추후안내]\n​\n보다 안정적인 서비스 제공과 회원 맞춤 일감 안내를 위해 신청 시스템이 개선되었습니다.\n기존과 동일하게 신청해 주시면 됩니다.\n​\n►대상 : 지난 12개월 이내 미용 피부과 또는 피부과 중심 에스테틱에서 아래 5개 분야의 서비스를 1개 이상 받은 성인 20~60세 여자대상\n1.주사 시술-> 보톡스, 필러, 바이오자극제(스컬트라,라디에스,쥬벨룩 볼륨,애스더필) 시술자\n2.바디 컨투어링-> 비침습 지방 감소(쿨스컬프팅클라투 알파, 피부 탄력 강화(울쎄라,써마지,슈링크 티타늄리프팅), 근육 자극 시술자\n3.모발 복원-> 처방용 외용제 및 경구약(피나스텔드, 미녹시딜), PRP(자가혈소판치료), 모발이식 수술자\n4.치료용 레이저-> 피부 재생(프락셀, CO2, 레이저 MD울트라),색소 교정(피코플러스,피코웨이,레블라이트SL,할리우드 레이저필), 혈관 및 주사(Vbeam, Excel v) 시술자\n5.다이어트 치료제-> 위고비, 마운자로, 삭센다 복용자\n►일정 :\n1.그룹 : 45~60세 여성 ->9월 2일(수) 오후 4시\n2.그룹 : 35~44세 여성 ->9월 2일(수) 오후 6시 15분\n3.그룹 : 20~34세 여성->9월 2일(수) 저녁 8시\n►소요 시간: 1시간 15분\n►장소 : 6호선 상수역 부근\n►사례비 : 컨택시\n​\n신청하기",
